ALTER TABLE buildpulse_ad_orders DROP CONSTRAINT IF EXISTS buildpulse_ad_orders_no_schedule_overlap; DROP EXTENSION IF EXISTS btree_gist; CREATE OR REPLACE FUNCTION buildpulse_schedule_ad_order(p_order_id UUID,p_starts_at TIMESTAMPTZ,p_ends_at TIMESTAMPTZ) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid UUID; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'service role required'; END IF; IF p_starts_at IS NULL OR p_ends_at IS NULL OR p_ends_at<=p_starts_at THEN RAISE EXCEPTION 'invalid schedule'; END IF; SELECT product_id INTO pid FROM buildpulse_ad_orders WHERE id=p_order_id AND status='approved' FOR UPDATE; IF pid IS NULL THEN RETURN FALSE; END IF; PERFORM 1 FROM buildpulse_ad_products WHERE id=pid FOR UPDATE; IF EXISTS(SELECT 1 FROM buildpulse_ad_orders WHERE product_id=pid AND id<>p_order_id AND status IN ('scheduled','active') AND starts_at<p_ends_at AND ends_at>p_starts_at) THEN RAISE EXCEPTION USING ERRCODE='23P01',MESSAGE='advertising inventory conflict'; END IF; UPDATE buildpulse_ad_orders SET status='scheduled',starts_at=p_starts_at,ends_at=p_ends_at,updated_at=NOW() WHERE id=p_order_id AND status='approved'; RETURN FOUND; END $$; REVOKE ALL ON FUNCTION buildpulse_schedule_ad_order(UUID,TIMESTAMPTZ,TIMESTAMPTZ) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION buildpulse_schedule_ad_order(UUID,TIMESTAMPTZ,TIMESTAMPTZ) TO service_role;